"use client";

import { useEffect, useRef, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import io, { type Socket } from "socket.io-client";
import { Loader2 } from "lucide-react";
import { getAllDroneOS, type DroneOS } from "@/lib/api/droneos";
import DroneController from "@/components/DroneController";
import type { DroneTelemetry } from "@/components/telemetry-window";
import DroneControllerNew from "@/components/DroneControllerNew";

const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000";

type DronePositionEvent = {
    id: string; // droneDbId
    lat: number;
    lng: number;
    alt?: number | null;
    ts: number;
};

export default function DroneControlPage() {
    const params = useParams<{ id: string }>();
    const droneId = params.id;
    const router = useRouter();

    const [drone, setDrone] = useState<DroneOS | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const [telemetry, setTelemetry] = useState<DroneTelemetry | null>(null);
    const [socketConnected, setSocketConnected] = useState(false);

    const socketRef = useRef<Socket | null>(null);
    const droneRef = useRef<DroneOS | null>(null);

    // ── Load this drone's last-known record (name, videoLink, targetAltitude) ──
    useEffect(() => {
        let cancelled = false;

        const load = async () => {
            setLoading(true);
            setError(null);
            try {
                // NOTE: swap this for a dedicated getDroneById(droneId) call if/when
                // one exists on the backend — fetching the whole list is what MapView
                // already does today, so this keeps behavior consistent for now.
                const res = await getAllDroneOS({ include: true });
                if (cancelled) return;

                if (res.success && res.data) {
                    const found = res.data.find((d) => d.id === droneId);
                    if (found) {
                        setDrone(found);
                        droneRef.current = found;
                    } else {
                        setError("Drone not found.");
                    }
                } else {
                    setError(res.error || "Failed to load drone.");
                }
            } catch (err) {
                console.error("[DroneControlPage] Error loading drone:", err);
                if (!cancelled) setError("Failed to load drone.");
            } finally {
                if (!cancelled) setLoading(false);
            }
        };

        if (droneId) load();

        return () => {
            cancelled = true;
        };
    }, [droneId]);

    // ── This page's own socket connection, filtered to just this drone ──
    useEffect(() => {
        if (!droneId) return;

        const s = io(API_BASE_URL, {
            reconnection: true,
            reconnectionDelay: 1000,
            reconnectionDelayMax: 5000,
            reconnectionAttempts: 5,
        });
        socketRef.current = s;

        s.on("connect", () => setSocketConnected(true));
        s.on("disconnect", () => setSocketConnected(false));

        s.on("drone_telemetry", (t: DroneTelemetry) => {
            if (t.droneDbId !== droneId) return; // ignore telemetry for other drones
            setTelemetry({
                ...t,
                videoLink: droneRef.current?.videoLink ?? null,
            });
        });

        s.on("drone_position", (pos: DronePositionEvent) => {
            if (pos.id !== droneId) return; // ignore positions for other drones
            setTelemetry((prev) =>
                prev
                    ? { ...prev, lat: pos.lat, lng: pos.lng, alt: pos.alt ?? prev.alt, ts: pos.ts }
                    : ({
                        droneDbId: droneId,
                        lat: pos.lat,
                        lng: pos.lng,
                        alt: pos.alt ?? null,
                        ts: pos.ts,
                        status: "ground",
                        videoLink: droneRef.current?.videoLink ?? null,
                    } as unknown as DroneTelemetry)
            );
        });

        return () => {
            s.disconnect();
            socketRef.current = null;
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [droneId]);

    if (loading) {
        return (
            <div className="flex h-screen w-full items-center justify-center bg-[#0d0d0d]">
                <div className="flex items-center gap-2 text-sm text-gray-400">
                    <Loader2 className="h-4 w-4 animate-spin" />
                    Loading drone...
                </div>
            </div>
        );
    }

    if (error || !drone) {
        return (
            <div className="flex h-screen w-full flex-col items-center justify-center gap-4 bg-[#0d0d0d] px-4 text-center">
                <p className="text-sm text-red-400">{error || "Drone not found."}</p>
                <button
                    onClick={() => router.push("/")}
                    className="rounded-lg border border-neutral-700 bg-neutral-800 px-4 py-2 text-sm text-white transition hover:bg-neutral-700"
                >
                    Back to map
                </button>
            </div>
        );
    }

    return (
        <DroneControllerNew
            variant="page"
            droneId={droneId}
            droneName={drone.droneOSName}
            currentAltitude={drone.targetAltitude ?? 0}
            telemetry={telemetry}
            socketConnected={socketConnected}
            onClose={() => router.back()}
        />
    );
}